# Pulumi ComponentResource: Service Infrastructure Wrapper

Here's a production-ready implementation of a Pulumi ComponentResource that wraps an S3 bucket, RDS PostgreSQL instance, and IAM role with environment-specific configuration.

## Main Implementation

```typescript
// index.ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

// ============================================================================
// Component Configuration Interface
// ============================================================================

export interface ServiceComponentArgs {
  bucketConfig?: {
    versioning?: boolean;
    encryption?: boolean;
    replication?: {
      enabled: boolean;
      destinationBucket?: string;
    };
  };
  rdsConfig?: {
    instanceClass: string;
    allocatedStorage: number;
    multiAz: boolean;
    backupRetentionDays: number;
    encrypted: boolean;
  };
  iamConfig?: {
    serviceName: string;
    oidcProvider?: {
      arn: string;
    };
  };
  tags?: Record<string, string>;
}

// ============================================================================
// Service ComponentResource
// ============================================================================

export class ServiceComponent extends pulumi.ComponentResource {
  public readonly bucket: aws.s3.Bucket;
  public readonly rdsInstance: aws.rds.Instance;
  public readonly iamRole: aws.iam.Role;

  public readonly bucketArn: pulumi.Output<string>;
  public readonly bucketName: pulumi.Output<string>;
  public readonly rdsEndpoint: pulumi.Output<string>;
  public readonly rdsAddress: pulumi.Output<string>;
  public readonly roleArn: pulumi.Output<string>;
  public readonly roleName: pulumi.Output<string>;

  constructor(
    name: string,
    args: ServiceComponentArgs,
    opts?: pulumi.ComponentResourceOptions
  ) {
    super("custom:service:ServiceComponent", name, {}, opts);

    const componentOpts = { parent: this };

    // ========================================================================
    // S3 Bucket: Versioning, Encryption, No Public Access
    // ========================================================================

    this.bucket = new aws.s3.Bucket(
      `${name}-bucket`,
      {
        acl: "private",
        forceDestroy: false,
        tags: args.tags,
      },
      componentOpts
    );

    // Enable versioning (required for dev & prod)
    if (args.bucketConfig?.versioning !== false) {
      new aws.s3.BucketVersioning(
        `${name}-versioning`,
        {
          bucket: this.bucket.id,
          versioningConfiguration: {
            status: "Enabled",
          },
        },
        componentOpts
      );
    }

    // Server-side encryption (AES-256)
    if (args.bucketConfig?.encryption !== false) {
      new aws.s3.BucketServerSideEncryptionConfiguration(
        `${name}-encryption`,
        {
          bucket: this.bucket.id,
          rule: {
            applyServerSideEncryptionByDefault: {
              sseAlgorithm: "AES256",
            },
          },
        },
        componentOpts
      );
    }

    // Block all public access
    new aws.s3.BucketPublicAccessBlock(
      `${name}-public-block`,
      {
        bucket: this.bucket.id,
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true,
      },
      componentOpts
    );

    // Cross-region replication (prod only)
    if (args.bucketConfig?.replication?.enabled) {
      const replicationRole = new aws.iam.Role(
        `${name}-replication-role`,
        {
          assumeRolePolicy: JSON.stringify({
            Version: "2012-10-17",
            Statement: [
              {
                Effect: "Allow",
                Principal: { Service: "s3.amazonaws.com" },
                Action: "sts:AssumeRole",
              },
            ],
          }),
        },
        componentOpts
      );

      new aws.iam.RolePolicy(
        `${name}-replication-policy`,
        {
          role: replicationRole.id,
          policy: pulumi.all([this.bucket.arn]).apply(
            ([bucketArn]) =>
              JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                  {
                    Effect: "Allow",
                    Action: [
                      "s3:GetReplicationConfiguration",
                      "s3:ListBucket",
                    ],
                    Resource: bucketArn,
                  },
                  {
                    Effect: "Allow",
                    Action: [
                      "s3:GetObjectVersionForReplication",
                      "s3:GetObjectVersionAcl",
                      "s3:GetObjectVersionTagging",
                    ],
                    Resource: `${bucketArn}/*`,
                  },
                  {
                    Effect: "Allow",
                    Action: [
                      "s3:ReplicateObject",
                      "s3:ReplicateDelete",
                      "s3:ReplicateTags",
                    ],
                    Resource: `arn:aws:s3:::${args.bucketConfig.replication?.destinationBucket}/*`,
                  },
                ],
              })
          ),
        },
        componentOpts
      );

      new aws.s3.BucketReplicationConfiguration(
        `${name}-replication`,
        {
          bucket: this.bucket.id,
          role: replicationRole.arn,
          rules: [
            {
              id: "replicate-all",
              status: "Enabled",
              filter: { prefix: "" },
              destination: {
                bucket: `arn:aws:s3:::${args.bucketConfig.replication?.destinationBucket}`,
                replicationTime: {
                  status: "Enabled",
                  time: { minutes: 15 },
                },
                metrics: {
                  status: "Enabled",
                  eventThreshold: { minutes: 15 },
                },
              },
            },
          ],
        },
        componentOpts
      );
    }

    // ========================================================================
    // RDS PostgreSQL: Deletion Protection, Encryption, No Public Access
    // ========================================================================

    const stackName = pulumi.getStack();
    const dbPasswordSecret = new pulumi.automation.StackReference(stackName)
      .getOutput("dbPassword")
      .apply((pw) => pw || "change-me");

    this.rdsInstance = new aws.rds.Instance(
      `${name}-db`,
      {
        identifier: `${name}-db-${stackName}`,
        engine: "postgres",
        engineVersion: "15.4",
        instanceClass: args.rdsConfig?.instanceClass || "db.t3.micro",
        allocatedStorage: args.rdsConfig?.allocatedStorage || 20,
        dbName: "appdb",
        username: "postgres",
        password: pulumi.secret(dbPasswordSecret),
        multiAz: args.rdsConfig?.multiAz || false,
        storageEncrypted: args.rdsConfig?.encrypted || false,
        backupRetentionPeriod: args.rdsConfig?.backupRetentionDays || 7,
        deleteProtection: true,
        skipFinalSnapshot: false,
        finalSnapshotIdentifierPrefix: `${name}-final`,
        publiclyAccessible: false,
        autoMinorVersionUpgrade: true,
        tags: args.tags,
      },
      componentOpts
    );

    // ========================================================================
    // IAM Role: Least-Privilege Service Account Access
    // ========================================================================

    let assumeRolePolicy: string;

    if (args.iamConfig?.oidcProvider) {
      // Production: IRSA (IAM Role for Service Accounts) via OIDC
      assumeRolePolicy = JSON.stringify({
        Version: "2012-10-17",
        Statement: [
          {
            Effect: "Allow",
            Principal: {
              Federated: args.iamConfig.oidcProvider.arn,
            },
            Action: "sts:AssumeRoleWithWebIdentity",
            Condition: {
              StringLike: {
                "oidc.eks.*.amazonaws.com/id/*:sub":
                  `system:serviceaccount:*:${args.iamConfig.serviceName}`,
              },
            },
          },
        ],
      });
    } else {
      // Development: Direct service trust
      assumeRolePolicy = JSON.stringify({
        Version: "2012-10-17",
        Statement: [
          {
            Effect: "Allow",
            Principal: {
              Service: "ec2.amazonaws.com",
            },
            Action: "sts:AssumeRole",
          },
        ],
      });
    }

    this.iamRole = new aws.iam.Role(
      `${name}-role`,
      {
        assumeRolePolicy,
        tags: args.tags,
      },
      componentOpts
    );

    // Least-privilege policy: S3 GET/LIST + RDS connect + describe
    new aws.iam.RolePolicy(
      `${name}-policy`,
      {
        role: this.iamRole.id,
        policy: pulumi.all([this.bucket.arn, this.rdsInstance.arn]).apply(
          ([bucketArn, rdsArn]) =>
            JSON.stringify({
              Version: "2012-10-17",
              Statement: [
                {
                  Sid: "S3ObjectAccess",
                  Effect: "Allow",
                  Action: ["s3:GetObject", "s3:ListBucket"],
                  Resource: [bucketArn, `${bucketArn}/*`],
                },
                {
                  Sid: "RDSAccess",
                  Effect: "Allow",
                  Action: [
                    "rds-db:connect",
                    "rds:DescribeDBInstances",
                  ],
                  Resource: rdsArn,
                },
              ],
            })
        ),
      },
      componentOpts
    );

    // Set outputs
    this.bucketArn = this.bucket.arn;
    this.bucketName = this.bucket.id;
    this.rdsEndpoint = this.rdsInstance.endpoint;
    this.rdsAddress = this.rdsInstance.address;
    this.roleArn = this.iamRole.arn;
    this.roleName = this.iamRole.name;

    this.registerOutputs({
      bucketName: this.bucketName,
      bucketArn: this.bucketArn,
      rdsEndpoint: this.rdsEndpoint,
      rdsAddress: this.rdsAddress,
      roleArn: this.roleArn,
      roleName: this.roleName,
    });
  }
}
```

## Stack Instantiation

```typescript
// index.ts (continued)

const config = new pulumi.Config();
const environment = pulumi.getStack(); // "dev" or "prod"
const isProduction = environment === "prod";

const serviceComponent = new ServiceComponent("app", {
  bucketConfig: {
    versioning: true,
    encryption: true,
    replication: isProduction
      ? {
          enabled: true,
          destinationBucket: config.require("replicationBucket"),
        }
      : undefined,
  },
  rdsConfig: {
    instanceClass: isProduction ? "db.t3.medium" : "db.t3.micro",
    allocatedStorage: isProduction ? 100 : 20,
    multiAz: isProduction,
    backupRetentionDays: isProduction ? 30 : 7,
    encrypted: isProduction,
  },
  iamConfig: {
    serviceName: config.require("serviceName"),
    oidcProvider: isProduction
      ? {
          arn: config.require("oidcProviderArn"),
        }
      : undefined,
  },
  tags: {
    Environment: environment,
    ManagedBy: "Pulumi",
  },
});

// Stack exports
export const bucketName = serviceComponent.bucketName;
export const bucketArn = serviceComponent.bucketArn;
export const rdsAddress = serviceComponent.rdsAddress;
export const rdsEndpoint = serviceComponent.rdsEndpoint;
export const roleArn = serviceComponent.roleArn;
export const roleName = serviceComponent.roleName;
```

## Stack Configuration Files

### Dev Stack (`Pulumi.dev.yaml`)

```yaml
config:
  aws:region: us-east-1
  custom:serviceName: app-dev
```

### Prod Stack (`Pulumi.prod.yaml`)

```yaml
config:
  aws:region: us-east-1
  custom:serviceName: app-prod
  custom:replicationBucket: app-prod-replica-us-west-2
  custom:oidcProviderArn: arn:aws:iam::ACCOUNT_ID:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEID
```

## Deployment

```bash
# Deploy to dev
pulumi stack select dev
pulumi up

# Deploy to prod
pulumi stack select prod
pulumi up
```

## Key Features

✅ **S3 Bucket**: Versioning, AES-256 encryption, public-access blocked  
✅ **RDS**: Deletion protection, 7+ day backup retention, no public access, encryption in prod  
✅ **IAM Role**: Least-privilege (S3 GET/LIST + RDS connect), OIDC trust in prod  
✅ **Environment Isolation**: Dev/prod parameters via stack configs; no shared state  
✅ **No Secrets in Git**: DB password injected via `pulumi.secret()` at deploy time  
✅ **Compliance**: Multi-AZ and encryption in prod only; single-AZ, unencrypted in dev
